import hmac,hashlib,json
from pathlib import Path
def canonical(obj):return json.dumps(obj,sort_keys=True,separators=(',',':'),ensure_ascii=False).encode()
def sign(root,files,key_id,key,expires):
 root=Path(root).resolve();manifest={}
 for name in sorted(files):
  if name.startswith('/')or '\\'in name or ':'in name or any(p in ('','.','..')for p in name.split('/')):raise ValueError('path')
  path=(root/name).resolve()
  if root not in path.parents:raise ValueError('outside')
  raw=path.read_bytes();manifest[name]={'size':len(raw),'sha256':hashlib.sha256(raw).hexdigest()}
 payload={'version':1,'key_id':key_id,'expires':expires,'files':manifest}
 return {'payload':payload,'signature':hmac.new(key,canonical(payload),hashlib.sha256).hexdigest()}
def verify(root,envelope,keys,now):
 payload=envelope['payload'];key=keys.get(payload['key_id'])
 if key is None:raise ValueError('unknown key')
 expected=hmac.new(key,canonical(payload),hashlib.sha256).hexdigest()
 if not hmac.compare_digest(expected,envelope['signature']):raise ValueError('signature')
 if payload['version']!=1 or now>=payload['expires']:raise ValueError('expired/version')
 generated=sign(root,payload['files'],payload['key_id'],key,payload['expires'])['payload']
 if generated!=payload:raise ValueError('artifact changed')
 return sorted(payload['files'])

